def fee(t):
    if t <= 2:
        return 1, f"3 * {t}", 3 * t
    elif t <= 6:
        return 2, f"6 + 2 * ({t} - 2)", 6 + 2 * (t - 2)
    else:
        return 3, "the cap", 14

cases = [
    ("zero hours", 0),
    ("inside the first piece", 1),
    ("the boundary 2", 2),
    ("inside the second piece", 5),
    ("the boundary 6", 6),
    ("past the cap", 9),
]
for label, t in cases:
    piece, work, value = fee(t)
    print(f"{label}: t = {t}")
    if piece == 1:
        print(f"  0 <= {t} <= 2 holds, so piece 1: {work} = {value}")
    elif piece == 2:
        print(f"  2 < {t} <= 6 holds, so piece 2: {work} = {value}")
    else:
        print(f"  {t} > 6 holds, so piece 3: {work} = {value}")

