cases = [
    ("the plain case", -1, 2, [-3, 0, 4]),
    ("a word problem, the warehouse", 1, 7, [0, 3, 9]),
    ("boundaries", -5, -2, [-5, -2]),
]
for label, a, b, xs in cases:
    print(f"{label}: g(x) = |x - ({a})| + |x - ({b})|, break points {a} and {b}")
    print(f"  x < {a}: both insides negative, ({a} - x) + ({b} - x) = -2x + ({a + b})")
    print(f"  {a} <= x < {b}: (x - ({a})) + ({b} - x) = {b - a}")
    print(f"  x >= {b}: both insides at least 0, 2x - ({a + b})")
    for x in xs:
        if x < a:
            piece = -2 * x + a + b
        elif x < b:
            piece = b - a
        else:
            piece = 2 * x - (a + b)
        print(f"  check x = {x}: pieces give {piece}, abs() gives {abs(x - a) + abs(x - b)}")

