from fractions import Fraction

limits = [0, 10000, 40000]
rates = [10, 20, 30]

n = int(input())
for i in range(n):
    income = int(input())
    total = Fraction(0)
    for j in range(3):
        lo = limits[j]
        if j < 2:
            hi = limits[j + 1]
        else:
            hi = income
        if income > lo:
            top = hi
            if income < hi:
                top = income
            total = total + Fraction((top - lo) * rates[j], 100)
    if income == 0:
        print("income 0: tax 0.00, no rate")
    else:
        print(f"income {income}: tax {total:.2f}, effective rate {100 * total / income:.2f}%")
